        void edge(AbstractModelObject from,Object to,String property){if(to instanceof PropertyChangeListener)edges.add(new Edge(from,(PropertyChangeListener)to,property));}
        Object at(Object raw)throws Exception{int id=index(raw,rows.size());Object value=objects.get(id);if(value==null)value=pseudo(id);return value;}
        <T>T at(Object raw,Class<T> type)throws Exception{Object value=at(raw);if(!type.isInstance(value))throw bad("Candidate reference type mismatch");return type.cast(value);}
