            for(int i=0;i<rows.size();i++)topology(i);
            for(int i=0;i<rows.size();i++)if(objects.get(i) instanceof PlacementsHolderLocation)locationDefinition(i);
            for(int i=0;i<rows.size();i++)if(objects.get(i) instanceof PlacementsHolder)holderDefinition(i);
            for(int i=0;i<rows.size();i++)if(objects.get(i) instanceof Placement&&"Placement".equals(rows.get(index(rows.get(i).get("definition"),rows.size())).get("type")))placementDefinition(i);
            for(int i=0;i<rows.size();i++)if(objects.get(i) instanceof Placement&&!"Placement".equals(rows.get(index(rows.get(i).get("definition"),rows.size())).get("type")))placementDefinition(i);
            for(int i=0;i<rows.size();i++)if("PseudoPlacement".equals(rows.get(i).get("type")))pseudo(i);
            for(int i=0;i<rows.size();i++)if(objects.get(i) instanceof Panel){Panel panel=(Panel)objects.get(i);IdentifiableList<Placement> list=new IdentifiableList<>();for(Object id:list(rows.get(i).get("pseudo"),10000)){Placement p=at(id,Placement.class);list.add(p);p.addPropertyChangeListener(panel);edge(p,panel,null);}panel.setPseudoPlacements(list);}
