            job.setErrorHandling(Job.ErrorHandling.valueOf(text(graph.get("error_handling"))));for(Object value:list(graph.get("overrides"),1000)){Map<String,Object> r=object(value);keys(r,"location","enabled","check_fiducials","placements");PlacementsHolderLocation<?> l=at(r.get("location"),PlacementsHolderLocation.class);job.storeEnabledState(l,null,bool(r.get("enabled")));job.storeCheckFiducialsState(l,bool(r.get("check_fiducials")));for(Object pv:list(r.get("placements"),10000)){Map<String,Object> pr=object(pv);keys(pr,"placement","enabled","error");Placement p=at(pr.get("placement"),Placement.class);job.storeEnabledState(l,p,bool(pr.get("enabled")));job.storeErrorHandlingState(l,p,Placement.ErrorHandling.valueOf(text(pr.get("error"))));}}
